// Global	    Across all collections/envs	   Universal values, quick prototyping
// Environment	Within selected environment	   Switching between Dev/QA/Prod setups
// Collection	Within one collection	       Shared values for that collection
// Local	    Only during request execution  Temporary chaining/debugging
// Data	        During collection run	       Data‑driven testing

const res=pm.response.json();
// Stored dynamic values:
pm.collectionVariables.set("bookingid1",res.bookingid);
pm.collectionVariables.set("firstname1",res.booking.firstname);
pm.collectionVariables.set("lastname1", res.booking.lastname);

console.log("First Name:-"+res.booking.firstname + " Last Name is " + res.booking.lastname);
// Status code validation:
pm.test("Checking status code",function(){
    pm.expect(pm.response.code).to.eql(200);
    pm.response.to.have.status(200);
});

pm.test("Checking response time",function(){
    pm.response.to.have.property("responseTime");
    // Response time validation:
    pm.expect(pm.response.responseTime).to.be.below(2000); // less than 2 seconds
})
pm.test("Checking Booking Id ",()=>{
    pm.expect(res).to.have.property("bookingid");
    pm.expect(res.bookingid).to.be.a("number");
    pm.expect(res.bookingid).to.eql(pm.collectionVariables.get("bookingid1"));
})

pm.test("Checking First Name and Last Name ", () => {
    pm.expect(res.booking).to.have.property("firstname");
    pm.expect(res.booking.firstname).to.be.a("string");
    pm.expect(res.booking.firstname).not.to.be.a("number");
    pm.expect(res.booking.firstname).to.eql(pm.collectionVariables.get("firstname1"));
    // Property existence checks:
    pm.expect(res.booking).to.have.property("lastname");
    // Type validation:
    pm.expect(res.booking.lastname).to.be.a("string");
    pm.expect(res.booking.lastname).to.eql(pm.collectionVariables.get("lastname1"));
});

const schema = {
    type: "object",
    properties: {
        bookingid: { type: "number" },
        booking: {
            type: "object",
            properties: {
                firstname: { type: "string" },
                lastname: { type: "string" }
            },
            required: ["firstname", "lastname"]
        }
    },
    required: ["bookingid", "booking"]
};
// Schema validation (optional but powerful):  
pm.test("Schema validation", () => {
    pm.expect(res).to.have.jsonSchema(schema);
});

const resByID= pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});


pm.test("Validating FirstName and LastNames",()=>{
    pm.expect(resByID).to.have.property("firstname");
    pm.expect(resByID.firstname).to.not.be.null;
    pm.expect(resByID.firstname).to.be.a("string");
    pm.expect(resByID.firstname).to.eql(pm.collectionVariables.get("firstname1"));

    pm.expect(resByID).to.have.property("lastname");
    pm.expect(resByID.lastname).to.not.be.null;
    pm.expect(resByID.lastname).to.be.a("string");
    pm.expect(resByID.lastname).to.eql(pm.collectionVariables.get("lastname1"));
})

